INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4808126, 693645, 15711, '<td valign="top">Nicely done. One of the few that meets the challenge in my opinion.</td>', 'Nicely done. One of the few that meets the challenge in my opinion.', '2008-07-07 01:04:21.000000', NULL, 1),
(4808142, 695340, 15711, '<td valign="top">Yikes.  Looks like you did a selective desaturation.  I hope I''m wrong.</td>', 'Yikes.  Looks like you did a selective desaturation.  I hope I''m wrong.', '2008-07-07 01:07:41.000000', NULL, 1),
(4808158, 695270, 714, '<td valign="top">Beautiful image! Love the composition, colors and subject.</td>', 'Beautiful image! Love the composition, colors and subject.', '2008-07-07 01:11:00.000000', NULL, 1),
(4808159, 694924, 89723, '<td valign="top">Just for Now!! Go Sox!! Great use of color.</td>', 'Just for Now!! Go Sox!! Great use of color.', '2008-07-07 01:11:24.000000', NULL, 1),
(4808161, 696060, 33068, '<td valign="top">Fabulous composition &amp; lighting.  Love it!</td>', 'Fabulous composition & lighting.  Love it!', '2008-07-07 01:12:49.000000', NULL, 1),
(4808198, 694700, 54446, '<td valign="top">Beautiful image.  Meets the challenge exceptionally well.  Clever use of yellow rain jacket in front of black and green.  The yellow and blue buttons and blue eyes are magnificent.  (10)</td>', 'Beautiful image.  Meets the challenge exceptionally well.  Clever use of yellow rain jacket in front of black and green.  The yellow and blue buttons and blue eyes are magnificent.  (10)', '2008-07-07 01:21:54.000000', NULL, 1),
(4808203, 695484, 29269, '<td valign="top">I just love the 2CV (my first car!!!) And, red to the point.</td>', 'I just love the 2CV (my first car!!!) And, red to the point.', '2008-07-07 01:23:06.000000', NULL, 1),
(4808217, 694082, 70369, '<td valign="top">The background seems to be having an issue.. I see a color change that arches over the group of pencils and the lone pencil.. Not sure if that was intentional..</td>', 'The background seems to be having an issue.. I see a color change that arches over the group of pencils and the lone pencil.. Not sure if that was intentional..', '2008-07-07 01:25:40.000000', NULL, 1),
(4808221, 694916, 70369, '<td valign="top">rather literal take on the challenge.. No DNMC here.. :-)..Could use a little more creativity. :-)</td>', 'rather literal take on the challenge.. No DNMC here.. :-)..Could use a little more creativity. :-)', '2008-07-07 01:26:15.000000', NULL, 1),
(4808227, 695319, 70369, '<td valign="top">clever take on the challenge. 7</td>', 'clever take on the challenge. 7', '2008-07-07 01:27:03.000000', NULL, 1),
(4808243, 696051, 70369, '<td valign="top">this has a lot of colors going on here.. She''s certainly very pretty and I think Pink is her color.. 4</td>', 'this has a lot of colors going on here.. She''s certainly very pretty and I think Pink is her color.. 4', '2008-07-07 01:28:27.000000', NULL, 1),
(4808246, 696074, 70369, '<td valign="top">I would like to see this one less sharpe and maybe some blur added.. I think the soft effect would have worked too.. 5</td>', 'I would like to see this one less sharpe and maybe some blur added.. I think the soft effect would have worked too.. 5', '2008-07-07 01:29:14.000000', NULL, 1),
(4808249, 694974, 70369, '<td valign="top">Precious and I love the soft focus.. Really sweet take on the challenge. 7</td>', 'Precious and I love the soft focus.. Really sweet take on the challenge. 7', '2008-07-07 01:29:57.000000', NULL, 1),
(4808252, 696124, 84520, '<td valign="top">Nice scene!  Since this is a ''point of color'' challenge, you''d do well to bring out the yellow in the flowers.  A hue/saturation layer would do the trick</td>', 'Nice scene!  Since this is a ''point of color'' challenge, you''d do well to bring out the yellow in the flowers.  A hue/saturation layer would do the trick', '2008-07-07 01:30:14.000000', NULL, 1),
(4808253, 695564, 15711, '<td valign="top">Not quite getting the black rose.  I think it would have been darling to just have the white negative space and her ruby lips. :~)</td>', 'Not quite getting the black rose.  I think it would have been darling to just have the white negative space and her ruby lips. :~)', '2008-07-07 01:30:16.000000', NULL, 1),
(4808259, 696098, 70369, '<td valign="top">how''d you get the pencil to stand up all by itself ??? I love the contrast between blue &amp; yellow.. One of my favorites.</td>', 'how''d you get the pencil to stand up all by itself ??? I love the contrast between blue & yellow.. One of my favorites.', '2008-07-07 01:31:30.000000', NULL, 1),
(4808261, 694578, 84520, '<td valign="top">Perhaps a different angle, with some trees or flowers in the background?  A blurry mess of green would contrast much better than a dull brown rocky backdrop.  The pink does stand out, but it doesn''t need to at the expense of the rest of the image</td>', 'Perhaps a different angle, with some trees or flowers in the background?  A blurry mess of green would contrast much better than a dull brown rocky backdrop.  The pink does stand out, but it doesn''t need to at the expense of the rest of the image', '2008-07-07 01:31:57.000000', NULL, 1),
(4808264, 696147, 71550, '<td valign="top">Let me guess.... this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=53147" rel="nofollow" target="_blank">timfythetoo</a>, right?</td>', 'Let me guess.... this is  timfythetoo, right?', '2008-07-07 01:32:08.000000', NULL, 1),
(4808265, 694974, 15711, '<td valign="top">Funny cause I went shopping to find a little girls dress today, to do the same thing.  I think just the dress alone would be better as this gives it two subjects instead of one.  Wish the purple were move vivid. Delicious bokeh. :~)</td>', 'Funny cause I went shopping to find a little girls dress today, to do the same thing.  I think just the dress alone would be better as this gives it two subjects instead of one.  Wish the purple were move vivid. Delicious bokeh. :~)', '2008-07-07 01:32:13.000000', NULL, 1),
(4808268, 695852, 84520, '<td valign="top">A colorful character, at least.  Nice DoF on this, even if it is a bit too ''snapshoty'' for my taste</td>', 'A colorful character, at least.  Nice DoF on this, even if it is a bit too ''snapshoty'' for my taste', '2008-07-07 01:32:48.000000', NULL, 1),
(4808278, 695078, 48228, '<td valign="top">Excellent, as it works for me.</td>', 'Excellent, as it works for me.', '2008-07-07 01:34:11.000000', NULL, 1),
(4808279, 694257, 84520, '<td valign="top">My two main critiques are the highlights on the grass (blown out) and the sharpness of the flag.  A flag waving in the air would be much more effective</td>', 'My two main critiques are the highlights on the grass (blown out) and the sharpness of the flag.  A flag waving in the air would be much more effective', '2008-07-07 01:34:18.000000', NULL, 1),
(4808282, 695522, 84520, '<td valign="top">I can''t find any technical flaws, however it lacks impact.  If you had come back in the evening or in the morning, with vibrant orange light striking the wall and highlighting the color of the flag, then you''d have a powerful scene.</td>', 'I can''t find any technical flaws, however it lacks impact.  If you had come back in the evening or in the morning, with vibrant orange light striking the wall and highlighting the color of the flag, then you''d have a powerful scene.', '2008-07-07 01:36:09.000000', NULL, 1),
(4808284, 695481, 84520, '<td valign="top">X marks the spot!  Nice image.</td>', 'X marks the spot!  Nice image.', '2008-07-07 01:36:31.000000', NULL, 1),
(4808296, 695474, 84520, '<td valign="top">I''ve found that most portraits benefit from a warm whitebalance--it brings out the skin tones and the eyes.  Right now, there isn''t enough tonal impact to make this effective.  She has pretty eyes, but they aren''t ''wow omigod blue!'', which they could be with a little more setup and some more PP.</td>', 'I''ve found that most portraits benefit from a warm whitebalance--it brings out the skin tones and the eyes.  Right now, there isn''t enough tonal impact to make this effective.  She has pretty eyes, but they aren''t ''wow omigod blue!'', which they could be with a little more setup and some more PP.', '2008-07-07 01:38:28.000000', NULL, 1),
(4808299, 695848, 84520, '<td valign="top">He seems a little blurry, and the texture and depth of his feathers is lacking.  Stronger light would help remedy both.</td>', 'He seems a little blurry, and the texture and depth of his feathers is lacking.  Stronger light would help remedy both.', '2008-07-07 01:39:32.000000', NULL, 1),
(4808300, 696080, 91663, '<td valign="top">Really striking image...I just wish the pencil color was something brighter. It  almost looks black and so doesn''t really exemplify the challenge. However, it definitely meets it, and so gets a 7.</td>', 'Really striking image...I just wish the pencil color was something brighter. It  almost looks black and so doesn''t really exemplify the challenge. However, it definitely meets it, and so gets a 7.', '2008-07-07 01:40:34.000000', NULL, 1),
(4808301, 695905, 84520, '<td valign="top">Good DoF and technical execution.  In my opinion, you should have found some roses in full bloom--I''d be saying ''wow!'' instead of ''meh''</td>', 'Good DoF and technical execution.  In my opinion, you should have found some roses in full bloom--I''d be saying ''wow!'' instead of ''meh''', '2008-07-07 01:40:55.000000', NULL, 1),
(4808310, 696164, 84520, '<td valign="top">If the head is your subject and point of color, then the DoF needs to extend from the beak to the back of the head, and it doesn''t.</td>', 'If the head is your subject and point of color, then the DoF needs to extend from the beak to the back of the head, and it doesn''t.', '2008-07-07 01:43:18.000000', NULL, 1),
(4808318, 695839, 67237, '<td valign="top">Irene, would it be too much to ask you to take a vacation from dpc? :-)</td>', 'Irene, would it be too much to ask you to take a vacation from dpc? :-)', '2008-07-07 01:50:01.000000', NULL, 1),
(4808320, 696119, 84520, '<td valign="top">Great isolation.  I can only do this with a BW conversion, so I''m pretty jealous that you pulled this off.</td>', 'Great isolation.  I can only do this with a BW conversion, so I''m pretty jealous that you pulled this off.', '2008-07-07 01:50:21.000000', NULL, 1),
(4808330, 695983, 84520, '<td valign="top">If the subject is the blue trash can, then it''s out of focus.  Since it''s overcast, you probably can''t shoot at a higher aperture and thus -need- to pay attention to the depth of field.    Other than that, this scene with the muddled sky and seemingly glum people has alot of potential.</td>', 'If the subject is the blue trash can, then it''s out of focus.  Since it''s overcast, you probably can''t shoot at a higher aperture and thus -need- to pay attention to the depth of field.    Other than that, this scene with the muddled sky and seemingly glum people has alot of potential.', '2008-07-07 01:52:23.000000', NULL, 1),
(4808334, 696077, 84520, '<td valign="top">It seems to be very overprocessed, but it''s also pretty damn cool.  I like the choice to center the composition in the lower right.</td>', 'It seems to be very overprocessed, but it''s also pretty damn cool.  I like the choice to center the composition in the lower right.', '2008-07-07 01:53:26.000000', NULL, 1),
(4808336, 695508, 84520, '<td valign="top">The light is a little harsh.  You''ll get better tones with a warmer whitebalance, which will also soften up the light.</td>', 'The light is a little harsh.  You''ll get better tones with a warmer whitebalance, which will also soften up the light.', '2008-07-07 01:54:02.000000', NULL, 1),
(4808341, 695522, 91131, '<td valign="top">nice job</td>', 'nice job', '2008-07-07 01:54:49.000000', NULL, 1),
(4808345, 695941, 84520, '<td valign="top">Yes Virginia, there IS color in that bowl!  My two criticisms are that it''s a little out of focus and that the swirls are bunched up and lack definition.  Pair a 5.6 aperture with a flash, and you''ll be able to shoot at a fast enough speed with enough DoF to capture this scene effectivly.</td>', 'Yes Virginia, there IS color in that bowl!  My two criticisms are that it''s a little out of focus and that the swirls are bunched up and lack definition.  Pair a 5.6 aperture with a flash, and you''ll be able to shoot at a fast enough speed with enough DoF to capture this scene effectivly.', '2008-07-07 01:55:48.000000', NULL, 1),
(4808347, 695852, 91131, '<td valign="top">great catch</td>', 'great catch', '2008-07-07 01:56:00.000000', NULL, 1),
(4808354, 696037, 84520, '<td valign="top">If the bottom blur was echoed around the border of this image (as in, a soft focus), then I''d be fine with it.  The scene is great and so is the light; when the foreground is out of focus, the image is often times unballanced and without an anchor (as is the case here).</td>', 'If the bottom blur was echoed around the border of this image (as in, a soft focus), then I''d be fine with it.  The scene is great and so is the light; when the foreground is out of focus, the image is often times unballanced and without an anchor (as is the case here).', '2008-07-07 01:58:03.000000', NULL, 1),
(4808361, 695078, 84520, '<td valign="top">The bottom left of the image is a tad blue, which I''m guessing is caused by reflection of light off the (paint?) and onto the background.   You''d do well to clone it out to white, because its pretty distracting left as-is.</td>', 'The bottom left of the image is a tad blue, which I''m guessing is caused by reflection of light off the (paint?) and onto the background.   You''d do well to clone it out to white, because its pretty distracting left as-is.', '2008-07-07 02:00:07.000000', NULL, 1),
(4808362, 695950, 91131, '<td valign="top">very nice image</td>', 'very nice image', '2008-07-07 02:00:07.000000', NULL, 1),
(4808364, 695671, 91131, '<td valign="top">beautiful</td>', 'beautiful', '2008-07-07 02:00:42.000000', NULL, 1),
(4808365, 695938, 84520, '<td valign="top">I''m probably going to see alot of fireworks--this is crisp, sharp, and beautiful.</td>', 'I''m probably going to see alot of fireworks--this is crisp, sharp, and beautiful.', '2008-07-07 02:00:49.000000', NULL, 1),
(4808375, 695747, 84520, '<td valign="top">I don''t like the crop.  Negative space is great, but with the six cubes placed at the right, they don''t even extend over the halfway point of the image.   Use negative space judiciously.</td>', 'I don''t like the crop.  Negative space is great, but with the six cubes placed at the right, they don''t even extend over the halfway point of the image.   Use negative space judiciously.', '2008-07-07 02:03:12.000000', NULL, 1),
(4808381, 695831, 84520, '<td valign="top">This would be so much cooler at night, with everything else faded to black.  It''s a nice spot, with the traffic light and the bend/hill in the road.  The basic elements of a good composition are here, but the rest of the image is just too distracting for it to have a powerful impact.</td>', 'This would be so much cooler at night, with everything else faded to black.  It''s a nice spot, with the traffic light and the bend/hill in the road.  The basic elements of a good composition are here, but the rest of the image is just too distracting for it to have a powerful impact.', '2008-07-07 02:04:53.000000', NULL, 1),
(4808384, 695465, 84520, '<td valign="top">I think at least three of the flowers should be in crisp focus in order for the image to have balance--currently, only one is.</td>', 'I think at least three of the flowers should be in crisp focus in order for the image to have balance--currently, only one is.', '2008-07-07 02:05:58.000000', NULL, 1),
(4808392, 695671, 37252, '<td valign="top">You nailed it! This is the first entry I have come across so far that I truly feel met the challenge head on. A great shot too.</td>', 'You nailed it! This is the first entry I have come across so far that I truly feel met the challenge head on. A great shot too.', '2008-07-07 02:08:08.000000', NULL, 1),
(4808393, 696116, 84520, '<td valign="top">I like how the center of the flower seems like the ''point'' of color, especially since it''s surrounded by a vibrant red petal!  I like your take on this challenge.</td>', 'I like how the center of the flower seems like the ''point'' of color, especially since it''s surrounded by a vibrant red petal!  I like your take on this challenge.', '2008-07-07 02:08:22.000000', NULL, 1),
(4808398, 695703, 84520, '<td valign="top">My one critique is that the light on the foreground row is pretty harsh.  There''s a loss of depth and texture that, to me, does the image in.</td>', 'My one critique is that the light on the foreground row is pretty harsh.  There''s a loss of depth and texture that, to me, does the image in.', '2008-07-07 02:09:18.000000', NULL, 1),
(4808402, 696111, 91131, '<td valign="top">super job</td>', 'super job', '2008-07-07 02:10:30.000000', NULL, 1),
(4808403, 694342, 84520, '<td valign="top">This is a minor technical quibble, but his beak is blurry.  Likewise, the yellow''s pretty muted.  It lacks zazz.</td>', 'This is a minor technical quibble, but his beak is blurry.  Likewise, the yellow''s pretty muted.  It lacks zazz.', '2008-07-07 02:10:41.000000', NULL, 1),
(4808407, 696083, 84520, '<td valign="top">Beautiful!  It looks like there''s some lens diffraction in the uper left corner of the lighthouse, which is easily fixed in PS.  You can either clone it out, or try your luck with the diffraction correction tool.  Other than that, it''s a nice shot.</td>', 'Beautiful!  It looks like there''s some lens diffraction in the uper left corner of the lighthouse, which is easily fixed in PS.  You can either clone it out, or try your luck with the diffraction correction tool.  Other than that, it''s a nice shot.', '2008-07-07 02:12:01.000000', NULL, 1),
(4808411, 696152, 84520, '<td valign="top">The light is too harsh on the boat.  With a polarizing filter, a lower exposure, and some tweaking of the levels, it would really stand out as a point of color.</td>', 'The light is too harsh on the boat.  With a polarizing filter, a lower exposure, and some tweaking of the levels, it would really stand out as a point of color.', '2008-07-07 02:12:44.000000', NULL, 1),
(4808412, 693662, 84520, '<td valign="top">They are, but the shot lacks impact.</td>', 'They are, but the shot lacks impact.', '2008-07-07 02:13:28.000000', NULL, 1),
(4808414, 696057, 91131, '<td valign="top">nice composition</td>', 'nice composition', '2008-07-07 02:14:13.000000', NULL, 1),
(4808419, 696035, 84520, '<td valign="top">I''m guessing you used a flash, because the light is harsh and facing your camera.  A good way to correct this is to use a diffusion filter over the flash, which provides a burst of light without the ''beam'' that causes a blowout of your highlights.    You can pay money for one, OR you can pick up a sample book of filters for FREE that literally has thousands of filters with descriptions of their use.  Simply cut them out, and use them!   You can even get an attachment that snaps onto your lens and lets you swap em out.  You have to pay 5 bucks for that, but it''s so worth it.</td>', 'I''m guessing you used a flash, because the light is harsh and facing your camera.  A good way to correct this is to use a diffusion filter over the flash, which provides a burst of light without the ''beam'' that causes a blowout of your highlights.    You can pay money for one, OR you can pick up a sample book of filters for FREE that literally has thousands of filters with descriptions of their use.  Simply cut them out, and use them!   You can even get an attachment that snaps onto your lens and lets you swap em out.  You have to pay 5 bucks for that, but it''s so worth it.', '2008-07-07 02:16:38.000000', NULL, 1),
(4808420, 696129, 84520, '<td valign="top">I love the reflections of color along the surface of the arch.</td>', 'I love the reflections of color along the surface of the arch.', '2008-07-07 02:17:01.000000', NULL, 1),
(4808425, 695875, 84520, '<td valign="top">The background is what does this image in.  A nice, green backdrop of trees (still out of the DoF) would be much more pleasant, and would highlight the color of his eye.  I''d be saying ''look at the pretty green, and OH! yellow eye!'' instead of ''that water looks dull''.  <br/> <br/>Just a thought.</td>', 'The background is what does this image in.  A nice, green backdrop of trees (still out of the DoF) would be much more pleasant, and would highlight the color of his eye.  I''d be saying ''look at the pretty green, and OH! yellow eye!'' instead of ''that water looks dull''.   Just a thought.', '2008-07-07 02:19:52.000000', NULL, 1),
(4808430, 695483, 84520, '<td valign="top">Nice capture.  The sharpness is great on the blue explosion.</td>', 'Nice capture.  The sharpness is great on the blue explosion.', '2008-07-07 02:20:22.000000', NULL, 1),
(4808431, 696025, 84520, '<td valign="top">gah! many hot pixils!  a photographers NIGHTMARE!</td>', 'gah! many hot pixils!  a photographers NIGHTMARE!', '2008-07-07 02:20:48.000000', NULL, 1),
(4808432, 695451, 84520, '<td valign="top">Thank you for a portrait that uses a point of color OTHER than the eyes</td>', 'Thank you for a portrait that uses a point of color OTHER than the eyes', '2008-07-07 02:21:22.000000', NULL, 1),
(4808437, 695906, 84520, '<td valign="top">The tilt is distracting.  You can correct it by going to your eyedropper tool in PS, clicking on the dragdown menu, and selecting the measure tool.  Drag it from one end of your crooked horizon to the other, then go to image--&gt;rotate---&gt;arbitrary.  You''ll have to do some croping, but you''re horizon will be fixed!</td>', 'The tilt is distracting.  You can correct it by going to your eyedropper tool in PS, clicking on the dragdown menu, and selecting the measure tool.  Drag it from one end of your crooked horizon to the other, then go to image-->rotate--->arbitrary.  You''ll have to do some croping, but you''re horizon will be fixed!', '2008-07-07 02:22:48.000000', NULL, 1),
(4808438, 695920, 84520, '<td valign="top">The lighting is dead.  Either get a shot in the evening, or up the white balance to a warmer tone (it won''t be the same as glorious sunset light, but it''ll be better)</td>', 'The lighting is dead.  Either get a shot in the evening, or up the white balance to a warmer tone (it won''t be the same as glorious sunset light, but it''ll be better)', '2008-07-07 02:23:39.000000', NULL, 1),
(4808456, 695641, 87808, '<td valign="top">i actually really love the negative space you have here</td>', 'i actually really love the negative space you have here', '2008-07-07 02:37:41.000000', NULL, 1),
(4808481, 694854, 84520, '<td valign="top">Strong composition and a nice use of a softer focus</td>', 'Strong composition and a nice use of a softer focus', '2008-07-07 03:03:31.000000', NULL, 1),
(4808483, 695106, 84520, '<td valign="top">Paintbrush is such a vibrant red, and this doesn''t convey the punch of color packed by this flower.  A hue/saturation layer would go a long way to giving this image more power</td>', 'Paintbrush is such a vibrant red, and this doesn''t convey the punch of color packed by this flower.  A hue/saturation layer would go a long way to giving this image more power', '2008-07-07 03:05:16.000000', NULL, 1),
(4808486, 695395, 84520, '<td valign="top">They seem a little grainy and out of focus.  Neatimage might work here.</td>', 'They seem a little grainy and out of focus.  Neatimage might work here.', '2008-07-07 03:05:57.000000', NULL, 1),
(4808487, 696085, 84520, '<td valign="top">I don''t see the point of color</td>', 'I don''t see the point of color', '2008-07-07 03:06:38.000000', NULL, 1),
(4808488, 695825, 84520, '<td valign="top">The point is to get laid?  Because that''s why peacock''s flash their feathers...</td>', 'The point is to get laid?  Because that''s why peacock''s flash their feathers...', '2008-07-07 03:07:28.000000', NULL, 1),
(4808491, 694786, 84520, '<td valign="top">This has a nice HDR feel.  I think the orange leaf could pack more punch, but overall, I like this image</td>', 'This has a nice HDR feel.  I think the orange leaf could pack more punch, but overall, I like this image', '2008-07-07 03:08:13.000000', NULL, 1),
(4808494, 696139, 84520, '<td valign="top">Nice PP.  I haven''t seen an image like this one before</td>', 'Nice PP.  I haven''t seen an image like this one before', '2008-07-07 03:08:46.000000', NULL, 1),
(4808497, 695980, 84520, '<td valign="top">I like the idea, but the composition needs work.  There''s a little too much negative space</td>', 'I like the idea, but the composition needs work.  There''s a little too much negative space', '2008-07-07 03:10:23.000000', NULL, 1),
(4808499, 695378, 84520, '<td valign="top">Beautiful!  I like how the entire image is vibrant and colorful, yet there is still a ''point of color''.<br/> <br/>Nice take on the challenge</td>', 'Beautiful!  I like how the entire image is vibrant and colorful, yet there is still a ''point of color''. Nice take on the challenge', '2008-07-07 03:11:08.000000', NULL, 1),
(4808501, 696126, 84520, '<td valign="top">He''s beautiful, but a little blurry.</td>', 'He''s beautiful, but a little blurry.', '2008-07-07 03:11:40.000000', NULL, 1),
(4808503, 695624, 84520, '<td valign="top">Beautiful!  I like the crisp and sharp colors against the black.</td>', 'Beautiful!  I like the crisp and sharp colors against the black.', '2008-07-07 03:12:28.000000', NULL, 1),
(4808506, 695564, 84520, '<td valign="top">The rose looks dead.  Is it supposed to?  Since I''m reading this image without any context, any intent for a ''dead'' rose needs to be clearly conveyed in the image.  Otherwise, I''m stuck thinking ''oh, I wish that was a beautiful and vibrant red rose''.<br/> <br/>It certainly would help, especially given the western symbolism of roses and women.</td>', 'The rose looks dead.  Is it supposed to?  Since I''m reading this image without any context, any intent for a ''dead'' rose needs to be clearly conveyed in the image.  Otherwise, I''m stuck thinking ''oh, I wish that was a beautiful and vibrant red rose''. It certainly would help, especially given the western symbolism of roses and women.', '2008-07-07 03:14:51.000000', NULL, 1),
