(4809957, 695728, 46177, '<td valign="top">Gorgeous, what a lovely blue and placing it on the delicate feather does make it look like a jewel. A well composed and very appealing image.</td>', 'Gorgeous, what a lovely blue and placing it on the delicate feather does make it look like a jewel. A well composed and very appealing image.', '2008-07-07 19:37:51.000000', NULL, 1),
(4809958, 693645, 70661, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2008-07-07 19:38:32.000000', NULL, 1),
(4809959, 695628, 46177, '<td valign="top">Fabulous job with the eyes, they are such an outstanding shade of green. The way she is looking off to the side really adds a sense of mystery, I wish I knew what she was looking at.</td>', 'Fabulous job with the eyes, they are such an outstanding shade of green. The way she is looking off to the side really adds a sense of mystery, I wish I knew what she was looking at.', '2008-07-07 19:38:57.000000', NULL, 1),
