(4812567, 695410, 76598, '<td valign="top">This might not do well because of the lens flare, the horizon is at 50% of the image and you would normally want it at 1/3 or 2/3, there appears to be a hot spot in the center where all detail is lost and the image doesn''t have a purpose....there isn''t a "story" being conveyed</td>', 'This might not do well because of the lens flare, the horizon is at 50% of the image and you would normally want it at 1/3 or 2/3, there appears to be a hot spot in the center where all detail is lost and the image doesn''t have a purpose....there isn''t a "story" being conveyed', '2008-07-08 20:52:46.000000', NULL, 1),
(4812570, 696167, 76598, '<td valign="top">This image might not do well because of the focus, even if it were in focus the contrast appears to be lacking as well.</td>', 'This image might not do well because of the focus, even if it were in focus the contrast appears to be lacking as well.', '2008-07-08 20:54:00.000000', NULL, 1),
(4812572, 695241, 76598, '<td valign="top">The focus appears to be off and the "mirror" light on the other side of the pole is distracting</td>', 'The focus appears to be off and the "mirror" light on the other side of the pole is distracting', '2008-07-08 20:54:53.000000', NULL, 1),
(4812575, 695831, 76598, '<td valign="top">To my eye the focus is soft, though a prolonged exposure tends to get soft.  To me the image lacks a theme as well, it''s just a street.</td>', 'To my eye the focus is soft, though a prolonged exposure tends to get soft.  To me the image lacks a theme as well, it''s just a street.', '2008-07-08 20:55:44.000000', NULL, 1),
