(4814783, 695910, 90658, '<td valign="top">This interpretation is almost opposite of the challenge, but it works quite nicely.  By making everything the atonal red, the green of the stems and the white of the floral hearts actually makes the flowers come alive.<br/> <br/>This is extremely counterintuitive and suggests that you have a gift for artistic design.</td>', 'This interpretation is almost opposite of the challenge, but it works quite nicely.  By making everything the atonal red, the green of the stems and the white of the floral hearts actually makes the flowers come alive. This is extremely counterintuitive and suggests that you have a gift for artistic design.', '2008-07-09 13:28:43.000000', NULL, 1),
(4814787, 695378, 90658, '<td valign="top">Very nice choice placing a soft pink inside of the harsher yellows and greens.</td>', 'Very nice choice placing a soft pink inside of the harsher yellows and greens.', '2008-07-09 13:29:19.000000', NULL, 1),
