(4819552, 695880, 52500, '<td valign="top">Your cheating what?  Oh wait...you mean "you''re cheating".  I get it.  It looks like she is smacking him in the head with the oar.  Aside from the title fiasco, it''s a good shot.  Certainly meets the challenge well.</td>', 'Your cheating what?  Oh wait...you mean "you''re cheating".  I get it.  It looks like she is smacking him in the head with the oar.  Aside from the title fiasco, it''s a good shot.  Certainly meets the challenge well.', '2008-07-11 16:36:16.000000', NULL, 1),
(4819641, 695319, 93411, '<td valign="top">Love this, only sug. would be clean the shelves so they don''t take the eye away from the pepper.  Other than that great shot 9/10</td>', 'Love this, only sug. would be clean the shelves so they don''t take the eye away from the pepper.  Other than that great shot 9/10', '2008-07-11 17:32:48.000000', NULL, 1),
(4819750, 696159, 3087, '<td valign="top">Beautiful! I''m a sucker for shallow DOF, especially used for wonderful plant macros!</td>', 'Beautiful! I''m a sucker for shallow DOF, especially used for wonderful plant macros!', '2008-07-11 18:54:34.000000', NULL, 1),
