(4819753, 695641, 3087, '<td valign="top">Cute concept.</td>', 'Cute concept.', '2008-07-11 18:55:49.000000', NULL, 1),
(4819754, 696057, 3087, '<td valign="top">Was this a serendipitous find or did you throw the ball/ buoy into the water? I like the shot, it has a slightly quirky nature and great composition.</td>', 'Was this a serendipitous find or did you throw the ball/ buoy into the water? I like the shot, it has a slightly quirky nature and great composition.', '2008-07-11 18:57:09.000000', NULL, 1),
(4819756, 695644, 3087, '<td valign="top">Lovely bird portrait and really like the monotone nature of foreground perch, background and bird''s plumage. Really makes the eye and beak stand out more.</td>', 'Lovely bird portrait and really like the monotone nature of foreground perch, background and bird''s plumage. Really makes the eye and beak stand out more.', '2008-07-11 18:58:27.000000', NULL, 1),
