(4822405, 695169, 76335, '<td valign="top">Well captured! Doesn''t fit comfortably into the challenge, but a great nature shot anyway.</td>', 'Well captured! Doesn''t fit comfortably into the challenge, but a great nature shot anyway.', '2008-07-13 19:00:22.000000', NULL, 1),
(4822407, 696044, 76335, '<td valign="top">Very creative. Well lit.</td>', 'Very creative. Well lit.', '2008-07-13 19:01:16.000000', NULL, 1),
(4822409, 695241, 76335, '<td valign="top">Shot at dusk, maybe, this would have had more impact. Still a creative idea.</td>', 'Shot at dusk, maybe, this would have had more impact. Still a creative idea.', '2008-07-13 19:02:01.000000', NULL, 1),
