(4822590, 695378, 76335, '<td valign="top">Terrific! The yellow on yellow background is a beautiful and effective backdrop. A seven for you.</td>', 'Terrific! The yellow on yellow background is a beautiful and effective backdrop. A seven for you.', '2008-07-13 22:18:28.000000', NULL, 1),
(4822593, 696037, 76335, '<td valign="top">I''m not sure how well this meets the challenge; I can''t identify a true singular point of color -- just the entire background. That quiblle aside, this is a beautifully composed and processed urban shot and the contrast between the darker foregound and bright colorful background is to good effect. A seven for you.</td>', 'I''m not sure how well this meets the challenge; I can''t identify a true singular point of color -- just the entire background. That quiblle aside, this is a beautifully composed and processed urban shot and the contrast between the darker foregound and bright colorful background is to good effect. A seven for you.', '2008-07-13 22:19:31.000000', NULL, 1),
(4822594, 695950, 76335, '<td valign="top">Beautifully lit, good use of negative space, thirds. A seven for you.</td>', 'Beautifully lit, good use of negative space, thirds. A seven for you.', '2008-07-13 22:19:59.000000', NULL, 1),
(4822596, 695981, 76335, '<td valign="top">Original. Well conceived and well executed. A seven for you.</td>', 'Original. Well conceived and well executed. A seven for you.', '2008-07-13 22:20:08.000000', NULL, 1),
(4822597, 695959, 76335, '<td valign="top">This is good. Maybe slightly oversaturated -- then again, maybe not. Not sure what time of day this was shot, but good job not overexposing this. An eight for you.</td>', 'This is good. Maybe slightly oversaturated -- then again, maybe not. Not sure what time of day this was shot, but good job not overexposing this. An eight for you.', '2008-07-13 22:20:20.000000', NULL, 1),
(4822598, 695848, 76335, '<td valign="top">Brilliant and fun. A seven for you.</td>', 'Brilliant and fun. A seven for you.', '2008-07-13 22:20:40.000000', NULL, 1),
(4822599, 695891, 76335, '<td valign="top">Beautifully clean processing. Excellent point of color. A seven for you.</td>', 'Beautifully clean processing. Excellent point of color. A seven for you.', '2008-07-13 22:20:48.000000', NULL, 1),
(4822600, 693884, 76335, '<td valign="top">That''s beautiful, in spite of the presumably uninvited spectators. A seven for you.</td>', 'That''s beautiful, in spite of the presumably uninvited spectators. A seven for you.', '2008-07-13 22:20:57.000000', NULL, 1),
(4822602, 695687, 76335, '<td valign="top">Great idea. I love the lighting and the textures. A seven for you.</td>', 'Great idea. I love the lighting and the textures. A seven for you.', '2008-07-13 22:21:20.000000', NULL, 1),
