(4824049, 695703, 27373, '<td valign="top">I really like this image.  I think I would''ve liked a bit more if the checkers around the base of the flowers had blended more into the larger checkers of the background.  Feels a little busy in that area.  I love the idea, when I read the description for this challenge I thought there would be about 200 black (or white) backgrounds with a marble, rubber duck or single flower.  But it turned out to be a very good challenge.  Great shot adding to favs.</td>', 'I really like this image.  I think I would''ve liked a bit more if the checkers around the base of the flowers had blended more into the larger checkers of the background.  Feels a little busy in that area.  I love the idea, when I read the description for this challenge I thought there would be about 200 black (or white) backgrounds with a marble, rubber duck or single flower.  But it turned out to be a very good challenge.  Great shot adding to favs.', '2008-07-14 12:36:19.000000', NULL, 0),
(4824053, 695728, 52549, '<td valign="top">Oh, this is a really beautiful image. Great shot, Heini!</td>', 'Oh, this is a really beautiful image. Great shot, Heini!', '2008-07-14 12:36:59.000000', NULL, 0),
(4824071, 695841, 52549, '<td valign="top">Very creative and I love the colour combination. Great work, Erik.</td>', 'Very creative and I love the colour combination. Great work, Erik.', '2008-07-14 12:41:39.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4824084, 695942, 52549, '<td valign="top">Simple and beautiful.</td>', 'Simple and beautiful.', '2008-07-14 12:45:17.000000', NULL, 0),
(4824092, 695703, 52549, '<td valign="top">I love the lighting on this, Shez. The whole thing is so crisp and clean. You''re so very good with these vibrant colours - this is a beautiful eyecatcher!</td>', 'I love the lighting on this, Shez. The whole thing is so crisp and clean. You''re so very good with these vibrant colours - this is a beautiful eyecatcher!', '2008-07-14 12:48:15.000000', NULL, 0),
(4824096, 695270, 27373, '<td valign="top">Okay, well technically this is three points of color- joking.  I have a real soft spot for the mirror like water reflection shots.  Too often you find the perfect reflection and the water won''t cooperate, or you find the perfect flat water and nothing to shoot.  Well done.  Congrats on your top ten.</td>', 'Okay, well technically this is three points of color- joking.  I have a real soft spot for the mirror like water reflection shots.  Too often you find the perfect reflection and the water won''t cooperate, or you find the perfect flat water and nothing to shoot.  Well done.  Congrats on your top ten.', '2008-07-14 12:49:14.000000', NULL, 0),
(4824106, 696060, 27373, '<td valign="top">When I see this shot for some reason I think Audrey Hepburn. Beautiful shot and great lighting, congrats on the ribbon.</td>', 'When I see this shot for some reason I think Audrey Hepburn. Beautiful shot and great lighting, congrats on the ribbon.', '2008-07-14 12:52:46.000000', NULL, 0),
(4824158, 695839, 90495, '<td valign="top">Congrats Irene. You''re inspiring.</td>', 'Congrats Irene. You''re inspiring.', '2008-07-14 13:20:25.000000', NULL, 0),
(4824160, 695078, 52549, '<td valign="top">Oh, yes! This is just the type of image I love. Great colour and a creative idea.</td>', 'Oh, yes! This is just the type of image I love. Great colour and a creative idea.', '2008-07-14 13:21:53.000000', NULL, 0),
(4824170, 695839, 67237, '<td valign="top">I knew this had to ribbon. Perfect balance and execution as usual. Congrats!!. <br/>It is amazing how you keep on re-inventing your macro style (and technics)... I''m kind of missing your good-old umbrella splashes :-)</td>', 'I knew this had to ribbon. Perfect balance and execution as usual. Congrats!!. It is amazing how you keep on re-inventing your macro style (and technics)... I''m kind of missing your good-old umbrella splashes :-)', '2008-07-14 13:25:54.000000', NULL, 0),
(4824174, 695848, 27373, '<td valign="top">You needed just a hint faster shutter speed to really freeze this one, theres just enough motion blur in the head and eyes to throw this shot off.  I spent two hours shooting flamingos at the Denver Zoo one day, my wife thought I was nuts.  I still didn''t get one as good as this.</td>', 'You needed just a hint faster shutter speed to really freeze this one, theres just enough motion blur in the head and eyes to throw this shot off.  I spent two hours shooting flamingos at the Denver Zoo one day, my wife thought I was nuts.  I still didn''t get one as good as this.', '2008-07-14 13:27:32.000000', NULL, 0),
(4824186, 696060, 63398, '<td valign="top">What a truly lovely image! Congrats on your ribbon!</td>', 'What a truly lovely image! Congrats on your ribbon!', '2008-07-14 13:33:38.000000', NULL, 0),
(4824188, 694916, 65083, '<td valign="top">Deb, I second SandyP you can take pictures of the most mudane stuff and turn it into art that I would frame and hang on my wall.</td>', 'Deb, I second SandyP you can take pictures of the most mudane stuff and turn it into art that I would frame and hang on my wall.', '2008-07-14 13:34:11.000000', NULL, 0),
(4824221, 695839, 52115, '<td valign="top">I think I''ll have to do a water drop and see how many votes I get. I don''t know how you do it, but you did it again. Congratulations.</td>', 'I think I''ll have to do a water drop and see how many votes I get. I don''t know how you do it, but you did it again. Congratulations.', '2008-07-14 13:47:24.000000', NULL, 0),
(4824274, 694617, 56539, '<td valign="top">Well, I guess that I really like your work now that it has been developed.  I voted a 10 on this without knowing who submitted it!  Another top ten for you. Congrats.</td>', 'Well, I guess that I really like your work now that it has been developed.  I voted a 10 on this without knowing who submitted it!  Another top ten for you. Congrats.', '2008-07-14 13:59:20.000000', NULL, 0),
(4824287, 695564, 27373, '<td valign="top">I think this would''ve scored much higher with both the face and the rose in sharp focus.  The idea behind this is very good.  Maybe some fill light into the face to help "blow out" the whiteness.</td>', 'I think this would''ve scored much higher with both the face and the rose in sharp focus.  The idea behind this is very good.  Maybe some fill light into the face to help "blow out" the whiteness.', '2008-07-14 14:04:23.000000', NULL, 0),
(4824300, 696147, 27373, '<td valign="top">Tim...what happened???<br/> <br/>Its not a bad photo, as always technically very good.  I think you got killed by the DNMC''rs here.  I think if you''d had a less blue sky-isn''t that something all photographers dream of, a bland grey dull sky  :), to go with the bright swimsuit it would''ve scored pretty well.</td>', 'Tim...what happened??? Its not a bad photo, as always technically very good.  I think you got killed by the DNMC''rs here.  I think if you''d had a less blue sky-isn''t that something all photographers dream of, a bland grey dull sky  :), to go with the bright swimsuit it would''ve scored pretty well.', '2008-07-14 14:06:55.000000', NULL, 0),
(4824323, 695913, 27373, '<td valign="top">I really like the concept here.  I think you may have gotten "slapped around" by the DNMC''rs.  To me this meets the challenge, but at the same time I can see why some people voted you down a bit for it, although honestly I don''t think it deserved the 2''s and 3''s it received.  Shame the flowers were there, I think if they hadn''t been this probably would''ve scored almost a point higher.<br/> <br/>The challenge aside.  I really like this image, and I honestly cannot explain why.  There is something about the contrast between the grittiness of the fence and the street in the background in contrast to the flowers.</td>', 'I really like the concept here.  I think you may have gotten "slapped around" by the DNMC''rs.  To me this meets the challenge, but at the same time I can see why some people voted you down a bit for it, although honestly I don''t think it deserved the 2''s and 3''s it received.  Shame the flowers were there, I think if they hadn''t been this probably would''ve scored almost a point higher. The challenge aside.  I really like this image, and I honestly cannot explain why.  There is something about the contrast between the grittiness of the fence and the street in the background in contrast to the flowers.', '2008-07-14 14:11:46.000000', NULL, 0),
(4824351, 695839, 52549, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by nutzito:</b></div><hr/><i> I''m kind of missing your good-old umbrella splashes :-) </i></td></tr></table> <br/>I''m biding my time, Alfredo ;-D</td>', 'Originally posted by nutzito: I''m kind of missing your good-old umbrella splashes :-)  I''m biding my time, Alfredo ;-D', '2008-07-14 14:21:33.000000', NULL, 0),
(4824401, 694924, 27373, '<td valign="top">Okay, well judging by the votes the voters consisted of 2 die hard Yankee fans, and 1 semi die hard Yankee fan.  But no die hard Red Sox fans (thus no tens).<br/> <br/>This is a very simple image, but well thought out.  The black background works very well and I really like the ????trunk top???? that its resting on.<br/> <br/></td>', 'Okay, well judging by the votes the voters consisted of 2 die hard Yankee fans, and 1 semi die hard Yankee fan.  But no die hard Red Sox fans (thus no tens). This is a very simple image, but well thought out.  The black background works very well and I really like the ????trunk top???? that its resting on. ', '2008-07-14 14:34:11.000000', NULL, 0),
(4824425, 695728, 71550, '<td valign="top">Very nice Heini. Go Germany!</td>', 'Very nice Heini. Go Germany!', '2008-07-14 14:47:36.000000', NULL, 0),
